-- Migration 6: daily tip bot. A bank of tips posted automatically as announcements, one per day.
create table if not exists public.tips (
  id uuid primary key default gen_random_uuid(),
  sort int not null default 0,
  category text default '',
  title text not null,
  body text not null default '',
  active boolean not null default true,
  posted_at timestamptz,
  created_at timestamptz default now()
);
alter table public.tips enable row level security;
drop policy if exists "tips admin" on public.tips;
create policy "tips admin" on public.tips for all to authenticated using (public.is_admin()) with check (public.is_admin());

alter table public.announcements add column if not exists kind text not null default 'manual'; -- 'manual' | 'tip'

insert into public.settings (key, value) values ('auto_tip', '{"enabled": true, "hour_et": 9}'::jsonb) on conflict (key) do nothing;

insert into public.tips (sort, category, title, body)
select * from (values
(1, 'Mindset', 'One build a day', 'You don''t need a perfect plan. You need one thing shipped today: a dashboard, a site, a DM, a call. Stack those and the plan writes itself.'),
(2, 'Mindset', 'Speed is the moat', 'Nobody in your town is faster than you at building AI tools. A business owner who sees a working demo in 48 hours doesn''t shop around.'),
(3, 'Mindset', 'Count attempts, not outcomes', 'You control messages sent and calls booked. You don''t control who says yes. Track the first, and the second takes care of itself.'),
(4, 'Mindset', 'Your first client is a learning fee', 'Charge, but don''t overthink the price on client one. The case study it gives you is worth more than the retainer.'),
(5, 'Mindset', 'Rejection is data', 'Every ''no'' tells you something: wrong niche, wrong offer, wrong message, or wrong timing. Write down which one and fix it before the next 20.'),
(6, 'Mindset', 'Don''t wait to feel ready', 'The students who land clients fastest start outreach in week one with a half-built demo. Readiness comes from reps, not from more videos.'),
(7, 'Mindset', 'Protect the streak', 'Points for daily activity are small on purpose. The habit is the point. Log in, do one thing, keep the streak alive.'),
(8, 'Mindset', 'Build in public', 'Post what you''re building, even if it''s ugly. Business owners buy from people who look busy and competent, and nothing says that like progress posts.'),
(9, 'Mindset', 'The leaderboard is a mirror', 'If you''re not where you want to be on it, look at your outreach count. It''s almost always the gap.'),
(10, 'Mindset', 'Stop collecting, start deploying', 'One tool you actually use beats ten you''ve signed up for. Pick Base44 plus one outreach channel and go deep.'),
(11, 'Mindset', 'Treat coaching calls like client meetings', 'Show up with your screen ready, a specific question, and your numbers. You''ll get ten times more out of Adriel and Jake.'),
(12, 'Mindset', 'Small niche, big results', 'Being the AI guy for dentists in one city beats being the AI guy for everyone, everywhere. Specificity sells.'),
(13, 'Niche & Offer', 'Pick a niche that already spends', 'Look for businesses that already pay for ads, software, or lead gen. If they''re spending, they understand ROI and your pitch is easier.'),
(14, 'Niche & Offer', 'Three questions for any niche', 'Do they have money? Do they have a painful, obvious problem? Can you reach the owner directly? Two out of three isn''t enough.'),
(15, 'Niche & Offer', 'Sell the outcome, not the tool', 'Nobody wants ''an AI agent.'' They want more booked appointments, fewer missed calls, faster quotes. Lead with the result.'),
(16, 'Niche & Offer', 'One offer, one price, one page', 'If your offer takes more than two sentences to explain, simplify it. Clear beats clever every time.'),
(17, 'Niche & Offer', 'Look at what they''re already paying for', 'If a med spa pays $800/month for a booking tool and $1,500 for an agency, a $1,000 AI system that does both is an easy yes.'),
(18, 'Niche & Offer', 'Steal the language', 'Read Google reviews and Facebook groups in your niche. The exact complaints customers write are your ad copy and your pitch.'),
(19, 'Niche & Offer', 'Local first', 'Local businesses answer the phone, meet in person, and refer each other. Start within driving distance. Scale out later.'),
(20, 'Niche & Offer', 'Guarantee something you control', 'Don''t guarantee revenue. Guarantee speed (''live in 7 days'') or effort (''we rebuild it free until it works''). Risk reversal that doesn''t bankrupt you.'),
(21, 'Niche & Offer', 'Price for the problem, not your hours', 'A tool that saves a roofer two lost jobs a month is worth $1,000+ regardless of whether it took you a weekend to build.'),
(22, 'Niche & Offer', 'Make a ''before and after'' slide', 'One slide: what their business looks like today, what it looks like with your system. Use it in every pitch.'),
(23, 'Niche & Offer', 'Avoid niches that argue about price', 'Restaurants and nail salons are tough. Contractors, dentists, lawyers, gyms, and med spas have margin and understand marketing.'),
(24, 'Niche & Offer', 'Name your system', '''The Lead Rescue System'' sounds like a product. ''An AI chatbot'' sounds like a commodity. Naming it lets you set the price.'),
(25, 'Build', 'Demo with their real data', 'Scrape their site, grab their services, use their logo. A demo built for them converts five times better than a generic one.'),
(26, 'Build', 'Start from a template, not a blank screen', 'In Base44, clone something that works and change the copy and colors. First versions should take an hour, not a day.'),
(27, 'Build', 'Ship the ugly version', 'A working dashboard with a plain layout beats a beautiful mockup that doesn''t work. Owners care if it functions, not if it''s pretty.'),
(28, 'Build', 'Build the demo before the call', 'Walk into every discovery call with something to show. ''Here''s what I already built for you'' changes the whole conversation.'),
(29, 'Build', 'One agent, one job', 'Super agents that try to do everything break. Build an agent that handles one thing perfectly (missed-call texts, quote follow-ups) and add from there.'),
(30, 'Build', 'Test it like a customer', 'Before you show a client, go through the whole flow on your phone as if you were their customer. Fix every friction point you hit.'),
(31, 'Build', 'Record a 2-minute Loom of every build', 'Walk through the dashboard on video. Send it instead of a long email. Prospects watch videos; they skim emails.'),
(32, 'Build', 'Connect the dashboard to something they already check', 'Owners live in their phone and their calendar. If your system texts them or drops into their calendar, they''ll actually use it.'),
(33, 'Build', 'Keep a portfolio page', 'Every build goes on one page with a screenshot and a one-line result. Link it in your bio and your outreach.'),
(34, 'Build', 'Reuse everything', 'Your second client in the same niche should take a third of the time. Save your prompts, layouts, and automations as templates.'),
(35, 'Build', 'Use Claude to write the copy', 'Ask it for headlines, service descriptions, and FAQ answers in the client''s voice. Edit, don''t start from zero.'),
(36, 'Build', 'Add one ''wow'' feature', 'An AI receptionist that answers in the owner''s name, a dashboard that shows revenue in real time. One feature they''ll show their friends.'),
(37, 'Outreach', 'Send 20 before you check results', 'Judging a message after three sends is noise. Send twenty, then look at replies and adjust.'),
(38, 'Outreach', 'Lead with their problem, not your pitch', '''Noticed your site doesn''t let people book online. Built a quick fix for you, want to see it?'' beats any intro about yourself.'),
(39, 'Outreach', 'Video DMs win', 'A 45-second screen recording of their website with your suggestions gets replies where text gets ignored.'),
(40, 'Outreach', 'Follow up five times', 'Most replies come on follow-up three or four. Space them out: day 1, 3, 7, 14, 30. Keep each one short and useful.'),
(41, 'Outreach', 'Call between 8 and 10 AM', 'Owners of local businesses answer their own phones before the day gets busy. Afternoons go to voicemail.'),
(42, 'Outreach', 'Walk in', 'For local niches, nothing beats showing up with a tablet and a demo. Ten walk-ins a week will book more than 200 cold emails.'),
(43, 'Outreach', 'Ask for the referral on day one', '''Who else do you know with the same problem?'' right after they say yes. Warm intros close at three times the rate.'),
(44, 'Outreach', 'Use the counter', 'Log every message, call, and DM in the Achievements tab. What gets measured gets done, and the badges unlock on their own.'),
(45, 'Outreach', 'Keep the first message under 50 words', 'Owners read on their phone. If it needs scrolling, it doesn''t get read.'),
(46, 'Outreach', 'Comment before you DM', 'Spend two days engaging with a prospect''s posts. Your DM lands as a familiar name instead of a stranger.'),
(47, 'Outreach', 'Build a list of 100', 'Don''t outreach from memory. Spreadsheet with name, business, phone, Instagram, status. Work the list top to bottom.'),
(48, 'Outreach', 'Post a case study every week', 'Even a small one. ''Built this for a local gym in 2 days, booked 11 trials in the first week.'' Inbound starts when people see results.'),
(49, 'Ads', 'One ad, one promise', 'Each ad makes one clear promise to one type of customer. Trying to say everything is how ads get ignored.'),
(50, 'Ads', 'Hook in the first 2 seconds', 'If the first line doesn''t name the viewer''s problem or desire, they scroll. Write ten hooks, test the best three.'),
(51, 'Ads', 'Script with AI, film with your phone', 'Use the ad scripting module to generate the structure, then record it yourself. Real beats polished for local businesses.'),
(52, 'Ads', 'Spy before you spend', 'Meta Ads Library and the Google Transparency Center show what competitors have been running for months. Long-running ads are working ads.'),
(53, 'Ads', 'Let an ad run 3 days before judging', 'Meta needs time to learn. Killing ads after 24 hours wastes every dollar you spent on them.'),
(54, 'Ads', 'Retarget everyone who visited', 'The cheapest conversions are people who already looked. Set up a retargeting audience before you run cold traffic.'),
(55, 'Ads', 'Creative is 80% of results', 'Targeting matters less every year. Spend your time on the hook, the visual, and the offer, not on interest stacks.'),
(56, 'Ads', 'Use client results as ads', 'A 15-second testimonial from a client is the best ad you''ll ever run for your own agency.'),
(57, 'Ads', 'Report three numbers', 'Owners don''t care about CPM. Show them leads, cost per lead, and booked appointments. Everything else is noise to them.'),
(58, 'Ads', 'Offer ads as the upsell', 'Build the system first, then say ''want me to send traffic to it?'' Ads become a second retainer, not a harder first sale.'),
(59, 'Ads', 'Refresh creative every two weeks', 'Ad fatigue is real. Rotate new hooks and visuals before results drop, not after.'),
(60, 'Ads', 'Keep the landing page to one action', 'One headline, one offer, one button. Every extra link is a leak.'),
(61, 'Closing', 'Ask about the problem for 10 minutes before pitching', 'The best closers talk 30% of the time. Let the owner describe their pain in their own words, then reflect it back.'),
(62, 'Closing', 'Show, don''t describe', 'Share your screen and click through the demo. Owners decide in the first 60 seconds of seeing something real.'),
(63, 'Closing', 'Anchor to what they already spend', '''You''re paying $2,000 a month for an answering service that misses calls. This is $800 and never sleeps.'''),
(64, 'Closing', 'Give two options, not one', 'A $750 setup plus $500/month and a $1,500 all-in. People pick between options more easily than they say yes or no to one.'),
(65, 'Closing', 'Handle ''let me think about it'' with a question', '''Totally fair. What''s the part you want to think through?'' Nine times out of ten it''s price or trust, and both are answerable.'),
(66, 'Closing', 'Send the Stripe link on the call', 'If they say yes, take payment while you''re still talking. ''I''ll send the invoice later'' loses a third of deals.'),
(67, 'Closing', 'Set the next step before hanging up', 'Onboarding call booked, logins requested, start date agreed. No call ends without a calendar event.'),
(68, 'Closing', 'Use the pricing module''s structure', 'Setup fee plus monthly retainer. The setup fee pays you for the build; the retainer builds the business.'),
(69, 'Closing', 'Silence after the price', 'Say the number, then stop talking. The first person to speak after the price is quoted usually loses.'),
(70, 'Closing', 'Record your calls', 'Listen back to one call a week. You''ll hear yourself over-explaining or skipping the ask. Nothing improves closing faster.'),
(71, 'Closing', 'Book the call for 20 minutes', 'Short calls get accepted. Owners say no to ''a quick hour'' and yes to ''twenty minutes to show you what I built.'''),
(72, 'Closing', 'The proposal is a recap, not a pitch', 'If you need a proposal to convince them, the call wasn''t done. The proposal should just confirm what you both agreed.'),
(73, 'Scale', 'Onboard in one session', 'A single 45-minute call: logins, phone number, calendar, go live. Drag it out over weeks and the client cools off.'),
(74, 'Scale', 'Weekly check-in, two lines', 'Every Friday: ''Here''s what the system did this week. Here''s what I''m improving next.'' Clients who hear from you don''t churn.'),
(75, 'Scale', 'Productize before you hire', 'Document every step of your build and onboarding. When it''s a checklist, you can hand it to someone else.'),
(76, 'Scale', 'Raise prices every third client', 'If your last three signed without pushback, your price is too low. Add 20% for the next one.'),
(77, 'Scale', 'Collect the testimonial at the first win', 'Ask the day they tell you about a result, not six months later. A text with a screenshot is enough.'),
(78, 'Scale', 'Three clients in one niche, then move', 'Three gives you a repeatable build, a case study, and referrals. Then either go deeper or add a second niche.'),
(79, 'Scale', 'Automate your own follow-up', 'You teach clients to follow up automatically. Do the same for your pipeline. Your own GHL should chase your leads.'),
(80, 'Scale', 'Check in on the Recordings page', 'Missed a call? The replay is there. The best questions from other students are usually the ones you''d have asked.'),
(81, 'Scale', 'Track monthly recurring revenue, not deals', 'A $500/month client is worth $6,000 a year. Build the business around retainers and the math gets fun fast.'),
(82, 'Scale', 'Stack systems for the same client', 'Dashboard, then AI receptionist, then ads, then a review engine. Four retainers from one client who already trusts you.'),
(83, 'Scale', 'Don''t abandon a client for a shiny niche', 'Your current clients are the easiest revenue you''ll ever get. Expand what you do for them before chasing new ones.'),
(84, 'Scale', 'Put your 30-day plan on paper', 'The Scale module gives you the template. Dates, numbers, actions. A plan you can see is a plan you follow.')
) as v(sort, category, title, body)
where not exists (select 1 from public.tips);
